<?php ob_start(); ?><h1><?= e(t('Trusted IPs')) ?></h1><p class="muted"><?= e(t('IP addresses known to be safe (admins, deploy tools, trusted maintainers). Used to reduce alert noise: a new file appearing in a site web root from a trusted IP will not trigger a notification.')) ?></p>
